CREATE TABLE inventory_reservation(tenant_id uuid NOT NULL,order_id uuid NOT NULL,sku_id uuid NOT NULL,warehouse_id uuid NOT NULL,quantity integer NOT NULL CHECK(quantity>0),status text NOT NULL CHECK(status IN ('RESERVED','RELEASED','CONSUMED')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,order_id,sku_id),FOREIGN KEY(tenant_id,order_id) REFERENCES sales_order(tenant_id,id),FOREIGN KEY(tenant_id,sku_id,warehouse_id) REFERENCES inventory(tenant_id,sku_id,warehouse_id));
INSERT INTO inventory_reservation(tenant_id,order_id,sku_id,warehouse_id,quantity,status)
 SELECT o.tenant_id,o.id,i.sku_id,o.warehouse_id,i.quantity,CASE o.status WHEN 'RESERVED' THEN 'RESERVED' WHEN 'SHIPPED' THEN 'CONSUMED' ELSE 'RELEASED' END FROM sales_order o JOIN order_item i ON i.order_id=o.id AND i.tenant_id=o.tenant_id WHERE o.status IN ('RESERVED','SHIPPED') OR EXISTS(SELECT 1 FROM inventory_movement m WHERE m.tenant_id=o.tenant_id AND m.order_id=o.id AND m.kind='reserve');
